INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(4400, 0, 44, 0, 0, 0, 'Redridge Mountains', 'The Redridge Mountains rise east of Elwynn Forest, a land of red stone ridges and wooded slopes gathered around the long waters of Lake Everstill, and all of it sovereign land of the King of Stormwind. Orcs have scarred these hills before: the Horde overran them in the First War, and Lakeshire was rebuilt only after the Second. Now war has returned. Blackrock orcs out of the Burning Steppes, aided by the dark magic of a renegade warlock named Morganth, have seized Stonewatch Keep and raid everything north of Lakeshire. Morganth himself holds the Tower of Ilgalar in the east, and the Shadowhide gnolls do his bidding. Redridge gnolls prowl the hills and the southern road, murlocs crowd the lakeshore, and the Everstill Bridge waits to be rebuilt. Magistrate Solomon pleads with Stormwind for soldiers, and in the meantime Lakeshire holds on with a handful of guards and whatever help passes through.', 'warcraft.wiki.gg/wiki/Redridge_Mountains (location, First War, Blackrock and Morganth seize the east and Stonewatch); warcraft.wiki.gg/wiki/Lakeshire (taken in the First War, rebuilt after the Second); quest 20 description (Blackrocks from the Burning Steppes, citizens penned in town); quest 128 description (sovereign right of the King of Stormwind); quests 91, 89, 125, 150, 244; quests 120-146 (Solomon''s pleas)'),
(4401, 1, 44, 1, 0, 0, 'Three Corners', 'Three Corners is the crossroads just inside the western edge of Redridge, where the road from Elwynn Forest divides, one way running northeast to Lakeshire and the other south toward Darkshire in Duskwood, so that the three shires of the kingdom meet here. In quieter years it needed little watching, and a single Stormwind guard, Guard Parker, still walks the stretch of road toward Duskwood. He has lately spotted gnoll encampments gathering to the north and east, not far from the Elwynn border. Tarantulas and Redridge mongrels lurk beside the roads, and a gnoll known as Ribchaser roams among them.', 'warcraft.wiki.gg/wiki/Three_Corners (crossroads to the three shires, quiet, patrolled by Guard Parker pre-Cataclysm); quest 129 description (Parker patrols the road leading to Duskwood); quest 244 description and reward text; DB: Guard Parker 464 at map 15,72; areaId 1002 holds Redridge Mongrel, Tarantula, Ribchaser 14271'),
(4402, 1, 44, 2, 0, 0, 'Lakeridge Highway', 'The Lakeridge Highway follows the southern shore of Lake Everstill across Redridge. It was once a well traveled road, but traffic dwindled after the orcs took Stonewatch Keep, and today gnolls hold much of its length. Deputy Feldon of Lakeshire, with no men of his own to spare, sends volunteers to harry the mongrels and poachers camped along the southern road and to count their numbers. Condors circle above the ridges, and black dragon whelps flit through the country south of Lakeshire, hunted by the town smith for their tough underbelly scales.', 'warcraft.wiki.gg/wiki/Lakeridge_Highway (road along the south of the lake, fell into disuse after Stonewatch fell, gnolls); quest 246 description and reward text; quest 122 description; DB: areaId 1001 holds Redridge Mongrel, Redridge Poacher, Dire Condor, Black Dragon Whelp'),
(4403, 1, 44, 3, 0, 0, 'Lakeshire', 'Lakeshire is the heart of Redridge, a town on the western shore of Lake Everstill. Taken by the Horde in the First War and rebuilt after the Second, it is under siege once again. Magistrate Solomon presides over the Court of Lakeshire from the town hall, Marshal Marris directs its few soldiers, and Verner Osgood keeps the stable and the forge. The inn stays open even as its bottles run dry, sheltering townsfolk and shadier guests, among them a rogue called Wiley who owes Gryan Stoutmantle a favor. The Everstill Bridge, which carries the road into town from the south, was blown out in the fighting, and Foreman Oslow''s crew labors to rebuild it with scarce iron.', 'warcraft.wiki.gg/wiki/Lakeshire (history, town hall and Court, inn); quest 116 description (bottles running dry); quests 65, 132 (Wiley in the inn); quests 118, 124, 1618 (Verner''s stable and smithing); quests 89, 125 (bridge blown out, iron short); quest 244 (Feldon south of the bridge); DB spawns: Solomon 344 at 30,44; Marris 382 and Oslow 341 at the bridge 32-34,49; Guard Howe at 31.5,58'),
(4404, 1, 44, 4, 0, 0, 'Lake Everstill', 'Lake Everstill fills the center of Redridge, its eastern river spilling down past Stonewatch toward the falls. The lake is famous for its spotted sunfish, but larger bands of murlocs have begun dropping anchor along its shores and fishing it bare, strangely far from the sea, as though something had driven them inland. Much has sunk beneath its surface. When orc catapults struck a boat carrying Foreman Oslow''s toolbox, the box went straight to the bottom, and a little girl fishing from the Lakeshire docks lost her father''s gift of a necklace to the water. The townsfolk warn their children of mean things below, and a great beast called the Lake Thresher prowls the deeps.', 'warcraft.wiki.gg/wiki/Lake_Everstill (center of Redridge, eastern river, murlocs, Lake Thresher); quest 127 description (famous for spotted sunfish); quest 150 description and reward text; quest 125 description; quest 3741 description and request text; DB: Lake Thresher 14357 and murlocs in areaId 68; Hilary 8962 and Shawn 8965 at the docks'),
(4405, 1, 44, 5, 0, 0, 'Redridge Canyons', 'North of Lakeshire the land climbs into the Redridge Canyons, a tangle of ridges and ravines where the Redridge gnolls make their home. Brutes and mystics prowl the ridge above Verner Osgood''s stable and carry off any horse that strays, and the pack''s baying drifts down to the town at night. Loudest of all is Yowler, the pack leader, who keeps his den in the canyons and is a far more dangerous foe than the mongrels who follow him. When a shipment of iron bound from Stormwind for the Everstill Bridge was hijacked, it was these gnolls who dragged it off into the hills behind the town.', 'warcraft.wiki.gg/wiki/Redridge_Canyons (northwest Redridge, Yowler''s den); quest 124 description and request text; quest 126 description; quest 89 description; DB: Yowler 518, Redridge Brute, Mystic, Basher, Alpha in areaId 95'),
(4406, 1, 44, 6, 0, 0, 'Rethban Caverns', 'The Rethban Caverns open in the foothills north of Lakeshire, named for Bart Rethban, the man who first found ore there. Rethban ore smelts weaker than iron, but its dark, flat color is prized by scribes who blend it into their dyes, and Lakeshire usually kept a supply. That has changed. Redridge gnolls have moved into the caverns, and their drudgers now dig the ore for themselves. The dwarf Yorus Barleybrew of the Lakeshire Inn has made the tunnels a test of nerve, the Rethban Gauntlet: a run to the first fork and back within the hour, through heaps of gnolls, after a swig of his family''s Barleybrew Scalder.', 'quest 347 description (Bart Rethban, ore, gnoll drudgers); quest 345 description; quest 1699 description; DB: Redridge Drudger 580 and Redridge Alpha 445 in areaId 98'),
(4407, 1, 44, 7, 0, 0, 'Render''s Camp', 'Where the road climbs out of Redridge toward the Burning Steppes, the Blackrock clan has made camp just west of the pass. From Render''s Camp the champions who lead each Blackrock unit direct the war on Lakeshire, trackers range the slopes around it, and an orc called Kazon is sometimes seen among them. Within the camp lies Render''s Rock, a large cave held by powerful Blackrock warriors. It was here that the orcs dragged Corporal Keeshan, taken alive in the bloody battle at Stonewatch Keep, to hold him as a prisoner of war.', 'warcraft.wiki.gg/wiki/Render''s_Camp (Blackrock outpost near the Burning Steppes entrance); warcraft.wiki.gg/wiki/Render''s_Rock (large cave, powerful Blackrock orcs, Keeshan); quest 128 description; page_text 245 (Missing: Corporal Keeshan); DB: Blackrock Champion 435 in areaId 998, Blackrock Tracker 615 in 996/998, Kazon 584 at 35,8, Keeshan 349 at 28,13'),
(4408, 1, 44, 8, 0, 0, 'Alther''s Mill', 'Northeast of Lakeshire, just off the road to Stonewatch, stands Alther''s Mill, an abandoned lumber mill. Most travelers pass it on their way east without stopping. Greater tarantulas have overrun the old timberworks, among them a monstrous spider called Chatter, and a black whelp named Snarlflare has been seen in the area. The quiet suits some. An associate of SI:7 who loiters on the Lakeshire docks has trained young thieves here for years, keeping lockboxes at the mill for them to crack, though he admits orcs have lately been seen nosing around the place.', 'warcraft.wiki.gg/wiki/Alther''s_Mill (abandoned lumber mill northeast of Lakeshire, travelers pass through); quest 2282 description and request text; quest 2281 description (Lucius, SI:7 associate, at the docks); DB: Chatter 616 (spider), Greater Tarantula 505, Snarlflare 14272, Practice Lockbox 178246 in areaId 97'),
(4409, 1, 44, 9, 0, 0, 'Stonewatch Falls', 'East of Stonewatch, the river that drains Lake Everstill tumbles down the slope and gathers in a deep pool in a hollow of the eastern mountains. A small band of murlocs fishes the pool and sleeps in rough shelters along its banks. The falls are no refuge, though. Blackrock outrunners and renegades, the raiders who ambush travelers on the roads between Lakeshire and the keep, range across the slopes here, and Shadowhide warriors from the valley to the north are never far away.', 'warcraft.wiki.gg/wiki/Stonewatch_Falls (river, pool, murlocs with shelters); quest 19 description (outrunners and renegades ambush between Lakeshire and Stonewatch); DB: areaId 71 holds Murloc Nightcrawler 544, Blackrock Outrunner 485, Blackrock Renegade 437, Shadowhide Warrior 568'),
(4410, 1, 44, 10, 0, 0, 'Stonewatch Keep', 'Stonewatch Keep once belonged to the people of Lakeshire. Then the Blackrock orcs came over the mountains from the Burning Steppes, and with the dark magic of the warlock Morganth behind them they stormed the keep. Most of the regiment that fought there was slain, and Corporal Keeshan was dragged away a prisoner. Now Warlord Gath''Ilzogg has made the keep his stronghold, plotting the clan''s next raids from within, while sentries, gladiators and shadowcasters bearing demon-tainted midnight orbs guard its halls. Beside it stands Stonewatch Tower, the one watch tower still intact, where the orcs keep scouts and summoners.', 'warcraft.wiki.gg/wiki/Stonewatch_Keep (held by Lakeshire, taken by Gath''Ilzogg with Morganth''s magic); quest 219 description (regiment overpowered, most men killed); quest 169 description; quest 115 description; quest 248 description (intact watch tower beside Stonewatch Keep); DB: Gath''Ilzogg 334, Singe, Sentry, Gladiator, Hunter, Shadowcaster in areaId 2099; Blackrock Scout and Summoner in 999'),
(4411, 1, 44, 11, 0, 0, 'Galardell Valley', 'Galardell Valley runs through the eastern foothills of Redridge, and it belongs to the Shadowhide gnolls. The Shadowhide answer to a master, the warlock Morganth, who speaks to them through the enchanted pendants they wear. Their camps crowd the valley under the command of Lieutenant Fangore, the strongest of them, and some of the clan have gone rabid. Lakeshire shows them no mercy. By the Law of Lakeshire, aiding a criminal of the kingdom is punishable by death, and the town''s bailiff has ordered every Shadowhide gnoll that serves Morganth hunted down.', 'warcraft.wiki.gg/wiki/Galardell_Valley (gnolls, Lieutenant Fangore strongest); warcraft.wiki.gg/wiki/Shadowhide_clan; quest 91 description; quest 178 description (pendants as communication with Morganth); DB: Fangore 703, Shadowhide Gnoll, Brute, Warrior, Rabid Shadowhide Gnoll 434 in areaId 1000; quest 91 description (gnolls aiding Morganth must be killed)'),
(4412, 1, 44, 12, 0, 0, 'Tower of Ilgalar', 'At the eastern edge of Redridge stands the Tower of Ilgalar, a mage tower now claimed by Morganth. Banished from Stormwind for embracing the dark arts, he carried off a powerful tome, Ur''s Treatise on Shadow Magic, and keeps it in his library here while Stormwind''s mages plot to win it back. Shadowhide darkweavers stand guard on the grounds and demonic servants roam the halls, among displays of dragon bones that hint at some study of dragons. Nearby, an old lion statue has kept lonely watch over the tower for decades.', 'warcraft.wiki.gg/wiki/Tower_of_Ilgalar (Morganth, dragon bones); quest 1938 description; quest 94 description and request text (Lion Statue); DB: Servant of Ilgalar 819 (demon), Shadowhide Darkweaver 429 in areaId 96; gameobject 103628 Ur''s Treatise in area 96; Old Lion Statue 31 at 84,47; warcraft.wiki.gg/wiki/Morganth (artifacts in the tower suggest he researched dragons)'),
(4413, 1, 44, 13, 0, 0, 'Render''s Valley', 'In the southeastern pocket of Redridge, below the mountains that divide it from the Swamp of Sorrows, lies Render''s Valley, a second Blackrock encampment far from the main host to the north. Grunts and summoners hold its camps, and Lakeshire has ordered them hunted as surely as those at Stonewatch. Not everyone in the valley is an orc. In one camp sits a captured servant of the Tower of Azora in Elwynn Forest, who still trades in fine tailoring supplies with any traveler who reaches him.', 'warcraft.wiki.gg/wiki/Render''s_Valley (southeastern Blackrock outpost, Captured Servant of Azora, pass to Swamp of Sorrows); quest 20 description (more Blackrocks in the southeastern pocket); DB: Blackrock Grunt 440 and Summoner 4463 in areaId 997; Captured Servant of Azora 3096 at 74,80'),
(4414, 2, 44, 1, 1, 0, 'Magistrate Solomon', 'Magistrate Solomon is the elected leader of Lakeshire and judge of its court, which sits in the town hall. With orcs at Stonewatch and gnolls in every hill, the township is under constant siege, and Solomon is certain that without reinforcements it will face defeat. He has written his most urgent report to General Marcus Jonathan in Stormwind, begging for soldiers. Meanwhile he posts bounties on the kingdom''s enemies, from the Blackrock warlord at Stonewatch to the gnoll lieutenant of Galardell Valley, and enforces the Law of Lakeshire against all who aid them.', 'warcraft.wiki.gg/wiki/Magistrate_Solomon (elected ruler, judge of the Court of Lakeshire); quests 120, 121, 143, 144, 145, 146 (descriptions and reward texts); quests 169, 180, 91'),
(4415, 2, 44, 2, 1, 0, 'Marshal Marris', 'Marshal Marris commands the defense of Lakeshire, keeping his post by the Everstill Bridge. His orders are simple: Blackrock orcs are to be hunted wherever they are found, from the heights of Stonewatch to the southeastern pocket of the mountains. He has put a price on Tharil''zun, leader of the outrunners who ambush the roads, and wants the shadowcasters'' demon-tainted midnight orbs taken and destroyed. It is Marris who rewards anyone who brings Corporal Keeshan home from the Blackrock camp. He found a moment, too, to name the troublesome local boar: Bellygrub.', 'warcraft.wiki.gg/wiki/Marshal_Marris (near the bridge, wants the orcs and Tharil''zun killed); quests 19, 20, 115 (descriptions); page_text 245 (reward by Marshal Marris); quest 219 (ends at Marris); quest 34 description (Bellygrub); DB: Marris 382 at 33.5,49, beside Foreman Oslow at the bridge; warcraft.wiki.gg/wiki/Marshal_Marris (near the bridge in Lakeshire)'),
(4416, 2, 44, 3, 1, 0, 'Corporal Keeshan', 'Corporal Keeshan of the 12th Sabre Regiment was at Stonewatch Keep when the Blackrock orcs overran it. Most of his comrades died in the fighting. Keeshan took a heavy blow to the head and woke a prisoner, dragged off to the Blackrock encampment at Render''s Rock near the pass to the Burning Steppes. A notice in Lakeshire lists him as missing. Badly hurt and unable to escape alone, he waits in the cave for any friend of the Alliance who might help him back to town, where he means to report to Marshal Marris for duty.', 'quest 219 description and reward text; creature_text 349 (12th Sabre Regiment, reporting for duty); page_text 245 (Missing: Corporal Keeshan); warcraft.wiki.gg/wiki/Corporal_Keeshan (dragged to Render''s Rock); DB: Keeshan 349 at 28,13'),
(4417, 2, 44, 4, 0, 0, 'Gath''Ilzogg', 'Gath''Ilzogg, Warlord of the Blackrock Clan, led the orc assault on Stonewatch Keep and the raids that have kept Lakeshire penned in ever since. Backed by the warlock Morganth''s magic, his warriors took the keep, and he has made it his stronghold, plotting the clan''s next blows with a black dragon whelp named Singe at his side. Many innocent people have died in his battles. His supreme executioner, Targorr the Dread, tortured captured defenders on a whim until he was taken and locked in the Stormwind Stockade, where a noble''s intervention has kept him from the headsman. Lakeshire offers a handsome reward for the warlord''s head.', 'warcraft.wiki.gg/wiki/Gath''Ilzogg (pre-Cataclysm: Warlord, Morganth alliance, Singe); quest 169 description and reward text; quest 386 description (Targorr the Dread); creature_text 334; DB: Gath''Ilzogg 334 and Singe 335 together in Stonewatch Keep'),
(4418, 2, 44, 5, 0, 0, 'Morganth', 'Morganth was once one of three mages who studied together in Stormwind, until he fell to the dark arts. Urged to turn away from them, he could not, and he was banished, taking with him a powerful tome, Ur''s Treatise on Shadow Magic. He settled in the Tower of Ilgalar in eastern Redridge and lent his magic to the Blackrock orcs in their assault on Stonewatch Keep. The Shadowhide gnolls of Galardell Valley now do his bidding, taking his commands through enchanted pendants, and Lakeshire calls him an enemy of the kingdom. In Elwynn Forest, his rival Theocritus watches him from afar.', 'quest 1938 description (three mages, fall, banishment, the treatise); warcraft.wiki.gg/wiki/Morganth; quest 91 description; quest 178 description; quests 94, 249 descriptions; DB: Morganth 397 at 80,50 in the tower'),
(4419, 2, 44, 6, 0, 0, 'Lieutenant Fangore', 'Lieutenant Fangore leads the Shadowhide gnoll clan in Morganth''s name and is the strongest of the gnolls who prowl Galardell Valley. Lakeshire counts him a traitor to Stormwind as much as a beast, and a wanted poster in town, issued by mandate of Magistrate Solomon, calls for his death with his paw as proof. Fangore is cunning as well as fierce. He seldom fights alone, and those who corner him often find the rest of his pack answering his call.', 'quest 180 description and reward text; warcraft.wiki.gg/wiki/Galardell_Valley (strongest gnoll, calls others for help); warcraft.wiki.gg/wiki/Shadowhide_clan; DB: Fangore 703 in areaId 1000; poster gameobject 47 in Lakeshire'),
(4420, 2, 44, 7, 0, 0, 'Tharil''zun', 'Tharil''zun leads the Blackrock outrunners, the swift raiders who, with renegades at their side, spring ambushes along the roads between Lakeshire and Stonewatch Keep. He is a vicious and crafty orc who stays close to the keep, and when cornered he flies into a rage. Marshal Marris has called for his head, for while Tharil''zun lives no traveler on the eastern roads is safe.', 'quest 19 description and reward text; creature_text 486 (becomes enraged); DB: Tharil''zun 486 at 69,60 in areaId 70 (Stonewatch)'),
(4421, 2, 44, 8, 1, 0, 'Verner Osgood', 'Verner Osgood runs the stable in Lakeshire and works as the town''s blacksmith, and he never has enough iron. Outfitting the Stormwind guards has used so much that he cannot shoe his own horses, and he has written to Smith Argus of Goldshire for a shipment of horseshoes. Gnolls on the ridge above his stable steal any horse that strays, and their leader Yowler howls in the hills. Verner is sure the army, busy with the orcs, has no soldiers to spare for the gnolls.', 'quests 118, 119, 122 (descriptions and reward texts); quests 124, 126 (descriptions and reward texts); quest 1618 reward text (fixing armor and making weapons for the troops)'),
(4422, 3, 44, 1, 1, 0, 'Letters from Lakeshire', 'Lakeshire is under constant siege. Blackrock orcs hold Stonewatch Keep, gnolls prowl the hills, and the town defends itself with only a handful of guards. Magistrate Solomon is certain that without reinforcements it will face defeat, and he has written his most urgent report to General Marcus Jonathan of Stormwind, begging for soldiers. The message is of the utmost importance. Whoever carries it must put it in the general''s hands and return to Lakeshire at once with whatever news he gives, be it good or bad.', 'quests 120, 121, 143, 144, 145, 146 (descriptions and reward texts)'),
(4423, 3, 44, 2, 1, 0, 'The Blackrock War', 'The Blackrock orcs came over the mountains from the Burning Steppes and, with Morganth''s sorcery to aid them, overwhelmed the defenders of Stonewatch Keep. Since then they have raided everything north of Lakeshire and kept its people penned in town like cattle. Until Stormwind''s army arrives, Lakeshire''s leaders turn to any willing sword. Marshal Marris pays for the battleworn axes of slain orcs, hunts the outrunner chief Tharil''zun, and wants the shadowcasters'' midnight orbs gathered and destroyed. Guard Howe calls for the champions who lead each Blackrock unit at their camp near the pass, and a wanted poster names Warlord Gath''Ilzogg himself, holed up in the conquered keep. Somewhere in the cave at Render''s Rock, a wounded Corporal Keeshan waits for rescue.', 'quests 19, 20, 115, 128, 169, 219 (descriptions and reward texts); page_text 245; warcraft.wiki.gg/wiki/Stonewatch_Keep'),
(4424, 3, 44, 3, 1, 0, 'Eyes on Ilgalar', 'Theocritus, high mage of the Tower of Azora in Elwynn Forest, watches his rival Morganth from afar through the Eye of Azora, a device of his own making. Seeing the warlock is not enough. To study his thoughts and learn his plans, Theocritus needs a Glyph of Azora set upon the old lion statue that has kept a lonely watch over the Tower of Ilgalar for decades. He has other means in hand as well. The Shadowhide gnolls who serve Morganth wear pendants through which their master speaks to them, and Theocritus has spent months of research trying to send his own voice through them.', 'quests 94, 248, 249, 178 (descriptions, request and reward texts); gameobjects 31 Old Lion Statue (ends 94, starts 248 and 249) and 76 An Empty Jar (ends 248) at Stonewatch Tower'),
(4425, 3, 44, 4, 1, 0, 'Gnolls in the Hills', 'Orcs are not Lakeshire''s only trouble. On the road to Duskwood, Guard Parker has spotted gnoll camps gathering north and east of his post, not far from the Elwynn border, and Lakeshire must be told. North of town, Redridge brutes and mystics prowl the ridge above Verner Osgood''s stable stealing his horses, and their leader Yowler howls in the hills, more dangerous than any of his pack. These same gnolls hijacked the iron meant for the Everstill Bridge and have moved into the Rethban Caverns to dig its ore for themselves. Verner is sure the Stormwind army is too busy with the orcs to spare anyone for the gnolls, and the work falls to volunteers.', 'quests 244, 246 (descriptions and reward texts); quests 124, 126 (descriptions and reward texts); quest 89 description; quest 347 description'),
(4426, 3, 44, 5, 1, 0, 'A Free Lunch', 'Not every tale in Lakeshire is one of war. Darcy, a waitress in town, has packed a lunch for Guard Parker, the big Stormwind guard who patrols the road toward Duskwood, but it is much too dangerous out there for a townsperson like her, and she dares not carry it out herself. Whoever takes it to him will find a free lunch waiting on their return. Elsewhere in town, the herbalist Martie Jainrose has troubles of her own: a boar Marshal Marris calls Bellygrub keeps trampling her garden, and she cannot replant her daffodils until next season.', 'quests 129, 130, 131 (descriptions and reward texts); quest 34 description');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(4414, 1, 0, 255, 'The general''s answer was warm: Solomon''s words carried great weight, the king would be consulted, and reinforcements would march as soon as His Majesty gave word. Yet Solomon found the letter something of a mystery. Something is amiss in the kingdom, he confided, and he feared this was the beginning of the conflict, not its end.', 'quest 120 reward text (General Marcus Jonathan''s reply); quest 121 reward text'),
(4414, 2, 0, 255, 'No soldiers came. Solomon turned next to Gryan Stoutmantle''s People''s Militia in Westfall and to Lord Ebonlocke''s Night Watch in Darkshire, only to learn that Stormwind''s army had abandoned them as well. The discovery shook him. He now speaks openly of treachery, and he means to get to the bottom of whatever is amiss in Stormwind.', 'quests 143, 144, 145 descriptions and reward texts; quest 146 description and reward text'),
(4418, 1, 0, 255, 'The alliance that took Stonewatch has soured. Peering into the Tower of Ilgalar through the Eye of Azora, Theocritus has seen that Morganth is now in conflict with the orcs of the keep, though the cause of their quarrel is still a mystery to him.', 'quest 248 description (Morganth is in conflict with the Orcs in Stonewatch Keep)'),
(4418, 2, 0, 255, 'Further watching uncovered the warlock''s purpose. Morganth searches for the Scythe of Elune, and Theocritus fears he may already have found it. If so, the high mage warns, Redridge and the whole kingdom of Stormwind will soon feel his dark might, and though he is not prepared to face his rival himself, he judges that Morganth must be dealt with now.', 'quest 249 description'),
(4418, 3, 0, 255, 'Morganth fell at last in the Tower of Ilgalar, struck down among the demonic servants that roam its halls. The banished mage who lent his sorcery to the conquest of Stonewatch, and who bent the Shadowhide gnolls of Galardell Valley to his will, is dead.', 'quest 249 reward text (in defeating the warlock Morganth); DB: Servant of Ilgalar 819 in areaId 96'),
(4421, 1, 0, 255, 'The horseshoes came, fifty of them boxed in a crate from Goldshire, and with them a note from Argus asking to be paid. Verner was indignant, but he means to settle the debt in the tough underbelly scales of the black dragon whelps that wander south of Lakeshire, with enough left over to fashion something for whoever gathers them.', 'quest 119 description and reward text; quest 122 description'),
(4422, 1, 0, 255, 'The general received the report kindly. Solomon was a noble leader, he said, whose words carried great weight, and he would seek the counsel of the king and make the situation plain. Lakeshire had the army''s support, and reinforcements would march as soon as word was given from His Majesty. Until then he sent a letter back to the magistrate.', 'quest 120 reward text; quest 121 description'),
(4422, 2, 0, 255, 'Back in Lakeshire, Solomon read the general''s letter and found it something of a mystery. Something was amiss in the kingdom, he said, and he feared this was the beginning of the conflict, not its end. He thanked the messenger for the service to Lakeshire and Stormwind, and waited for the king''s word.', 'quest 121 reward text'),
(4422, 3, 0, 255, 'The army should have been there in force by then, and still it did not come. Unwilling to stand by while the people of Lakeshire gave their lives, Solomon looked elsewhere for help. Word had reached him of a people''s militia forming in Westfall, and he wrote to its leader, Gryan Stoutmantle, asking for men until the king sent reserves.', 'quest 143 description'),
(4422, 4, 0, 255, 'Stoutmantle''s reply was heavy. The magistrate, he wrote, could not know the war being waged in Westfall, or he would not look to the militia for aid: had Stormwind not deserted Westfall too, there would be no need for a militia at all, and his heart was heavy with the loss of good men. Solomon was dismayed to find Stoutmantle''s plight so like his own, and asked what could call the army away from its own people. He wrote next to Lord Ebonlocke of Darkshire, asking for the Night Watch.', 'quest 144 description and reward text; quest 145 description'),
(4422, 5, 0, 255, 'Ebonlocke''s answer was the same. Had he not known Solomon, he wrote, he would think the man mad: the Night Watch was formed because Stormwind left Duskwood when foul magic seeped into the land, and if it marched, Darkshire would be overrun before the guards reached the forest''s edge. The army had retreated from Westfall and no longer guarded Darkshire. Solomon now suspects treachery, and he means to discover what is amiss in Stormwind.', 'quest 146 description and reward text'),
(4423, 1, 0, 255, 'Keeshan made it home. Wounded and slow, he was helped out of the Blackrock cave and past the orc camps to Lakeshire, where he stood before Marshal Marris and reported for duty, a soldier of the 12th Sabre Regiment returned from battle. Marris counted the help given in his escape a fine service to the kingdom.', 'quest 219 reward text; creature_text 349 (wounds, reporting for duty to Marshal Marris); script npc_corporal_keeshan: escort ends at waypoint 115 beside Marshal Marris (spawn -9284,-2298), where Keeshan reports'),
(4423, 2, 0, 255, 'In time the warlord himself fell. When Gath''Ilzogg''s head was laid before Magistrate Solomon, the magistrate named him the orc who had led those brutes into battle and killed so many innocent people, and declared that vindication was Lakeshire''s at last. This, he said, was the first step in reclaiming Stonewatch Keep for the kingdom of Stormwind.', 'quest 169 reward text'),
(4424, 1, 0, 255, 'The pendant experiment worked after all. Theocritus had sent his message into the Shadowhide pendants weeks before and believed it a failure, but it reached at least some of them after a long delay. In time he hopes to send an attack the same way, to hold fast any gnoll who wears one, though much more research is needed first.', 'quest 178 description and reward text'),
(4424, 2, 0, 255, 'The glyph took hold on the statue, and through it Theocritus''s voice can now be heard. What he saw troubled him: Morganth is in conflict with the orcs of Stonewatch Keep, for reasons he cannot yet tell. To unravel it, he wanted a second glyph hidden atop the intact watch tower beside the keep, in some chest or jar where no one would notice it.', 'quest 94 request and reward texts; quest 248 description'),
(4424, 3, 0, 255, 'An empty liquor jar left forgotten on a pair of barrels made a fine hiding place, and through it Theocritus delved into the minds within Stonewatch Keep. After long observation he learned Morganth''s plans. The warlock seeks the Scythe of Elune and may already have found it. Unready to face his rival himself, Theocritus judged that Morganth must be dealt with now, and sent champions into the Tower of Ilgalar to defeat him and bring back his Pendant of Shadow.', 'quest 248 request and reward texts; quest 249 description; gameobjects 31 Old Lion Statue (ends 94, starts 248 and 249) and 76 An Empty Jar (ends 248) at Stonewatch Tower'),
(4424, 4, 0, 255, 'The Pendant of Shadow lies in Theocritus''s hands, and Morganth is defeated. Stormwind, the high mage declares, has been saved from a grave peril. He offers his thanks humbly, and would bid peace to the one who did it if these were peaceful times; instead he wishes them luck in their trials and victory in the conflicts ahead.', 'quest 249 reward text'),
(4425, 1, 0, 255, 'Deputy Feldon took the news hard. Redridge gnolls that close to Elwynn might be poised to advance into the kingdom''s heartland, and then Lakeshire''s people would not be the only humans under siege. With no men to spare, he sends volunteers down the southern road to harry the mongrels and poachers camped along it and to bring back a count of their strength.', 'quest 244 reward text; quest 246 description'),
(4425, 2, 0, 255, 'The count is grim. A sizable force of gnolls is camped along the southern road, and a tough one, and it was no easy thing to gather even that much. Lakeshire''s situation, Feldon admits, grows ever more desperate, and he sends the scouts on to Marshal Marris and Magistrate Solomon.', 'quest 246 reward text'),
(4425, 3, 0, 255, 'Yowler is dead. The pack leader was hunted down in the hills above Lakeshire and his paw brought to Verner as proof, and the loudest of the cries that kept the stable uneasy at night has fallen silent. Verner is grateful, and no less sure that the army, busy with the orcs, has no troops to protect Redridge from the gnolls.', 'quest 126 description and reward text; quest 124 request text (the wolf cry at night)'),
(4426, 1, 0, 255, 'Parker was delighted with the meal, for guarding Lakeshire from orcs and gnolls is tough work, and he wanted to send flowers back to Darcy. There was one condition. They had to come from Martie''s herbalist shop at the west end of town, and Martie must not learn whom they were from, or whom they were for.', 'quest 129 request and reward texts; quest 130 description'),
(4426, 2, 0, 255, 'Martie asked no names, though she could not resist teasing a newcomer who seemed to have found a sweetheart so quickly. It was nice, she said, to see love in the air, especially in dangerous times like these, and she made up a bouquet of daffodils, her own favorite flowers.', 'quest 130 reward text; quest 131 description'),
(4426, 3, 0, 255, 'Darcy loved the bouquet, until she looked at it closely. Daffodils were Martie''s favorite flowers. Parker had not sent the messenger to that jealous vixen, had he? And surely no one had told Martie whom they were for, because if they had, it would not surprise Darcy if she had poisoned them.', 'quest 131 reward text');
